def _get_deliveryslip_report_title(self):
    self.ensure_one()
    return self.picking_type_id._get_code_report_name()

def _get_packages_for_print(self):
    package_ids = OrderedSet()
    for picking in self:
        if picking.state == 'done':
            package_ids.update(picking.package_history_ids.package_id.ids)
        else:
            package_ids.update(picking.move_line_ids.result_package_id._get_all_package_dest_ids())
    return self.env['stock.package'].browse(package_ids)

def on_modification(cls, mode, carriers, field_names=None):
    pool = Pool()
    CarrierSelection = pool.get('carrier.selection')
    super().on_modification(mode, carriers, field_names=field_names)
    if mode in {'create', 'delete'}:
        CarrierSelection._get_carriers_cache.clear()

def get_carriers(cls, pattern):
    pool = Pool()
    Carrier = pool.get('carrier')

    key = tuple(sorted(pattern.items()))
    carriers = cls._get_carriers_cache.get(key)
    if carriers is not None:
        return Carrier.browse(carriers)

    carriers = []
    selections = cls.search([])
    if not selections:
        with inactive_records():
            carriers = Carrier.search([])
    else:
        for selection in selections:
            if (selection.match(pattern)
                    and selection.carrier not in carriers):
                carriers.append(selection.carrier)

    cls._get_carriers_cache.set(key, list(map(int, carriers)))
    return carriers

def __setup__(cls):
    super().__setup__()
    selection = ('weight', 'Weight')
    if selection not in cls.carrier_cost_method.selection:
        cls.carrier_cost_method.selection.append(selection)

def compute_weight_price(self, weight):
    "Compute price based on weight"
    line = None
    for line in reversed(self.weight_price_list):
        if line.weight < weight:
            return line.price
    else:
        if line and not line.weight and not weight:
            return line.price
    return Decimal(0)

def _get_weight_price(self):
    weights = Transaction().context.get('weights', [])
    if weights:
        weight_price = sum(
            self.compute_weight_price(w) for w in weights)
    else:
        weight_price = self.compute_weight_price(0)
    return weight_price, self.weight_currency.id

def get_sale_price(self):
    price, currency_id = super().get_sale_price()
    if self.carrier_cost_method == 'weight':
        price, currency_id = self._get_weight_price()
    return price, currency_id

def get_purchase_price(self):
    price, currency_id = super().get_purchase_price()
    if self.carrier_cost_method == 'weight':
        price, currency_id = self._get_weight_price()
    return price, currency_id

@Override
@Transactional(rollbackOn = Exception.class)
public String computeFreightCarrierPricing(
    List<FreightCarrierPricing> freightCarrierPricingList, Long saleOrderId)
    throws AxelorException {
  SaleOrder saleOrder = saleOrderRepository.find(saleOrderId);
  if (saleOrder != null) {
    this.checkSelectedFreightPricingMode(freightCarrierPricingList);
    FreightCarrierPricing freightCarrierPricing = freightCarrierPricingList.get(0);
    saleOrder.setFreightCarrierMode(
        freightCarrierModeRepository.find(freightCarrierPricing.getFreightCarrierMode().getId()));
    saleOrder.setCarrierPartner(
        partnerRepository.find(freightCarrierPricing.getCarrierPartner().getId()));
    saleOrder.setShippingCost(freightCarrierPricing.getPricingAmount());

    if (saleOrder.getEstimatedShippingDate() != null) {
      saleOrder.setEstimatedDeliveryDate(
          saleOrder
              .getEstimatedShippingDate()
              .plusDays(freightCarrierPricing.getDelay().longValue()));
    }

    String message =
        saleOrderShipmentService.createShipmentCostLine(saleOrder, saleOrder.getShipmentMode());
    saleOrderRepository.save(saleOrder);
    return message;
  }
  return null;
}

public Set<FreightCarrierPricing> getFreightCarrierPricingSet(
    Long shipmentModeId, Long saleOrderId) {
  Set<FreightCarrierPricing> freightCarrierPricings = new HashSet<>();
  SaleOrder saleOrder = saleOrderRepository.find(saleOrderId);

  List<FreightCarrierMode> freightCarrierModeList =
      freightCarrierModeRepository
          .all()
          .filter("self.shipmentMode.id = :id")
          .bind("id", shipmentModeId)
          .fetch();

  if (!freightCarrierModeList.isEmpty() && saleOrder != null) {
    freightCarrierModeList.forEach(
        fc -> {
          freightCarrierPricings.add(this.createFreightCarrierPricing(fc, saleOrder));
        });
  }

  return freightCarrierPricings;
}

@Override
public FreightCarrierPricing createFreightCarrierPricing(
    FreightCarrierMode freightCarrierMode, SaleOrder saleOrder) {

  if (freightCarrierMode == null) {
    return null;
  }

  FreightCarrierPricing freightCarrierPricing = new FreightCarrierPricing();
  freightCarrierPricing.setFreightCarrierMode(freightCarrierMode);
  freightCarrierPricing.setCarrierPartner(freightCarrierMode.getCarrierPartner());
  freightCarrierPricing.setPricing(freightCarrierMode.getFreightCarrierPricing());
  freightCarrierPricing.setDelayPricing(freightCarrierMode.getFreightCarrierDelay());
  freightCarrierPricing.setSaleOrder(saleOrder);
  return freightCarrierPricing;
}

@Override
public void updateEstimatedDeliveryDateWithPricingDelay(SaleOrder saleOrder)
    throws AxelorException {
  FreightCarrierPricing freightCarrierPricing =
      this.createFreightCarrierPricing(saleOrder.getFreightCarrierMode(), saleOrder);

  if (freightCarrierPricing == null) {
    return;
  }

  Pricing delay =
      Optional.of(freightCarrierPricing).map(FreightCarrierPricing::getDelayPricing).orElse(null);

  String errors =
      freightCarrierApplyPricingService.computeFreightCarrierPricing(
          delay, freightCarrierPricing);

  if (errors.length() > 0) {
    throw new AxelorException(
        TraceBackRepository.CATEGORY_CONFIGURATION_ERROR,
        I18n.get(SupplychainExceptionMessage.FREIGHT_CARRIER_MODE_PRICING_ERROR),
        errors);
  }

  saleOrder.setEstimatedDeliveryDate(
      saleOrder
          .getEstimatedShippingDate()
          .plusDays(freightCarrierPricing.getDelay().longValue()));
}

@Override
public String notifyEstimatedDeliveryDateUpdate(SaleOrder saleOrder) {
  FreightCarrierMode freightCarrierMode = saleOrder.getFreightCarrierMode();
  if (freightCarrierMode == null) {
    return null;
  }

  Pricing delayPricing = freightCarrierMode.getFreightCarrierDelay();
  if (delayPricing != null) {
    return I18n.get(SupplychainExceptionMessage.SALE_ORDER_ESTIMATED_SHIPPING_DATE_NOT_UPDATED);
  }

  return null;
}

@Override
public StockMove createStockMove(
    Address fromAddress,
    Address toAddress,
    Company company,
    Partner clientPartner,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    LocalDate realDate,
    LocalDate estimatedDate,
    String note,
    ShipmentMode shipmentMode,
    FreightCarrierMode freightCarrierMode,
    Partner carrierPartner,
    Partner forwarderPartner,
    Incoterm incoterm,
    int typeSelect)
    throws AxelorException {

  StockMove stockMove =
      this.createStockMove(
          fromAddress,
          toAddress,
          company,
          fromStockLocation,
          toStockLocation,
          realDate,
          estimatedDate,
          note,
          typeSelect);
  stockMove.setPartner(clientPartner);
  stockMove.setShipmentMode(shipmentMode);
  stockMove.setFreightCarrierMode(freightCarrierMode);
  stockMove.setCarrierPartner(carrierPartner);
  stockMove.setForwarderPartner(forwarderPartner);
  if (appStockService.getAppStock().getIsIncotermEnabled()) {
    stockMove.setIncoterm(incoterm);
  }
  stockMove.setNote(note);
  stockMove.setIsIspmRequired(stockMoveToolService.getDefaultISPM(clientPartner, toAddress));

  return stockMove;
}

@Override
public StockMove createStockMove(
    Address fromAddress,
    Address toAddress,
    Company company,
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    LocalDate realDate,
    LocalDate estimatedDate,
    String note,
    int typeSelect)
    throws AxelorException {

  StockMove stockMove = new StockMove();

  if (stockMove.getStockMoveLineList() == null) {
    stockMove.setStockMoveLineList(new ArrayList<>());
  }

  stockMove.setFromAddress(fromAddress);
  stockMove.setToAddress(toAddress);
  stockMoveToolService.computeAddressStr(stockMove);
  stockMove.setCompany(company);
  stockMove.setStatusSelect(StockMoveRepository.STATUS_DRAFT);
  stockMove.setRealDate(realDate);
  stockMove.setEstimatedDate(estimatedDate);
  stockMove.setFromStockLocation(fromStockLocation);
  stockMove.setToStockLocation(toStockLocation);
  stockMove.setNote(note);
  stockMove.setPrintingSettings(
      Beans.get(TradingNameService.class).getDefaultPrintingSettings(null, company));

  stockMove.setTypeSelect(typeSelect);
  stockMove.setIsWithBackorder(company.getStockConfig().getIsWithBackorder());
  if (typeSelect == StockMoveRepository.TYPE_INCOMING) {
    stockMove.setIsWithReturnSurplus(company.getStockConfig().getIsWithReturnSurplus());
  }
  return stockMove;
}

@Override
public StockMove createStockMoveMobility(
    StockLocation fromStockLocation,
    StockLocation toStockLocation,
    Company company,
    List<StockMoveLine> stockMoveLines)
    throws AxelorException {

  StockMove stockMove = createStockMoveMobility(fromStockLocation, toStockLocation, company);
  this.plan(stockMove);
  if (stockMoveLines != null) {
    for (StockMoveLine stockMoveLine : stockMoveLines) {
      // This method will already set sml.stockMove = stockMove so no need to add in list.
      createStockMoveLine(stockMove, stockMoveLine);
    }
  }

  this.realize(stockMove);

  return stockMove;
}

@Transactional(rollbackOn = {Exception.class})
protected StockMove createStockMoveMobility(
    StockLocation fromStockLocation, StockLocation toStockLocation, Company company) {
  StockMove stockMove = new StockMove();
  stockMove.setStatusSelect(StockMoveRepository.STATUS_DRAFT);
  stockMove.setTypeSelect(StockMoveRepository.TYPE_INTERNAL);
  stockMove.setCompany(company);
  stockMove.setFromStockLocation(fromStockLocation);
  stockMove.setFromAddress(fromStockLocation.getAddress());
  stockMove.setToStockLocation(toStockLocation);
  stockMove.setToAddress(toStockLocation.getAddress());
  stockMove.setNote(""); // comment to display on stock move
  stockMove.setPickingOrderComments(""); // comment to display on picking order
  stockMove.setRealDate(LocalDate.now());
  stockMove.setEstimatedDate(LocalDate.now());
  return stockMoveRepo.save(stockMove);
}

@Transactional(rollbackOn = {Exception.class})
protected StockMoveLine createStockMoveLine(StockMove stockMove, StockMoveLine stockMoveLine)
    throws AxelorException {

  Product product = stockMoveLine.getProduct();
  stockMoveLineService.setProductInfo(stockMove, stockMoveLine, stockMove.getCompany());

  TrackingNumberConfiguration trackingNumberConfiguration =
      (TrackingNumberConfiguration)
          productCompanyService.get(
              product, "trackingNumberConfiguration", stockMove.getCompany());
  if (trackingNumberConfiguration != null) {
    stockMoveLine.setTrackingNumber(stockMoveLine.getTrackingNumber());
  }

  if (stockMoveLine.getToStockLocation() == null) {
    stockMoveLine.setToStockLocation(stockMove.getToStockLocation());
  }

  if (stockMoveLine.getFromStockLocation() == null) {
    stockMoveLine.setFromStockLocation(stockMove.getFromStockLocation());
  }

  stockMoveLine.setIsRealQtyModifiedByUser(true);
  stockMoveLine.setUnitPriceUntaxed(product.getLastPurchasePrice());
  stockMove.addStockMoveLineListItem(stockMoveLine);
  stockMoveLineRepo.save(stockMoveLine);
  stockMoveLineService.setAvailableStatus(stockMoveLine, stockMove);
  stockMoveLineService.compute(stockMoveLine, stockMove);
  return stockMoveLineRepo.save(stockMoveLine);
}

