def on_submit(self):
	if not self.shipment_parcel:
		frappe.throw(_("Please enter Shipment Parcel information"))
	if flt(self.value_of_goods) <= 0:
		frappe.throw(_("Value of goods must be greater than 0"))
	self.db_set("status", "Submitted")

def validate_weight(self):
	for parcel in self.shipment_parcel:
		if flt(parcel.weight) <= 0:
			frappe.throw(_("Parcel weight cannot be 0"))

		if cint(parcel.count) < 1:
			frappe.throw(_("Row #{0}: Parcel count must be at least 1").format(parcel.idx))

		for fieldname in ("length", "width", "height"):
			if flt(parcel.get(fieldname)) < 0:
				frappe.throw(
					_("Row #{0}: Parcel {1} cannot be negative").format(
						parcel.idx, _(parcel.meta.get_label(fieldname))
					)
				)

def validate_pickup_time(self):
	if self.pickup_from and self.pickup_to and get_time(self.pickup_to) <= get_time(self.pickup_from):
		frappe.throw(_("Pickup To time should be greater than Pickup From time"))

	if (self.is_new() or self.has_value_changed("pickup_date")) and getdate(self.pickup_date) < getdate():
		frappe.throw(_("Pickup Date cannot be before today"))

def validate_parties(self):
	for side, party_type in (("pickup", self.pickup_from_type), ("delivery", self.delivery_to_type)):
		party = self.get(f"{side}_{frappe.scrub(party_type)}")
		if not party:
			frappe.throw(_("{0} is required for the {1} party").format(_(party_type), _(side.title())))

		for other_type in ("Company", "Customer", "Supplier"):
			if other_type != party_type:
				self.set(f"{side}_{frappe.scrub(other_type)}", None)

		self.set("pickup" if side == "pickup" else "delivery_to", party)
		if self.is_new() or self.has_party_details_changed(side):
			self.validate_party_links(side, party_type, party)

def has_party_details_changed(self, side):
	return any(
		self.has_value_changed(f"{side}_{fieldname}")
		for fieldname in ("company", "customer", "supplier", "address_name", "contact_name")
	)

def validate_party_links(self, side, party_type, party):
	for doctype, fieldname in (("Address", f"{side}_address_name"), ("Contact", f"{side}_contact_name")):
		name = self.get(fieldname)
		if name and not is_linked_to_party(doctype, name, party_type, party):
			frappe.throw(
				_("{0} {1} is not linked to {2} {3}").format(
					_(doctype), bold(name), _(party_type), bold(party)
				)
			)

def validate_delivery_notes(self):
	delivery_notes = set()
	for row in self.get("shipment_delivery_note"):
		if row.delivery_note in delivery_notes:
			frappe.throw(
				_("Row #{0}: Delivery Note {1} is added more than once").format(
					row.idx, bold(row.delivery_note)
				)
			)

		delivery_notes.add(row.delivery_note)
		self.validate_delivery_note_row(row)

def validate_delivery_note_row(self, row):
	lock = self.docstatus == 1
	delivery_note = frappe.db.get_value(
		"Delivery Note",
		row.delivery_note,
		["docstatus", "customer", "base_grand_total"],
		as_dict=True,
		for_update=lock,
	)
	if delivery_note.docstatus != 1:
		frappe.throw(
			_("Row #{0}: Delivery Note {1} must be submitted").format(row.idx, bold(row.delivery_note))
		)

	if self.delivery_to_type == "Customer" and delivery_note.customer != self.delivery_customer:
		frappe.throw(
			_("Row #{0}: Delivery Note {1} belongs to Customer {2}").format(
				row.idx, bold(row.delivery_note), bold(delivery_note.customer)
			)
		)

	if shipment := get_other_shipment(row.delivery_note, self.name, for_update=lock):
		frappe.throw(
			_("Row #{0}: Delivery Note {1} is already in Shipment {2}").format(
				row.idx, bold(row.delivery_note), get_link_to_form("Shipment", shipment)
			)
		)

	row.grand_total = delivery_note.base_grand_total

def set_value_of_goods(self):
	value_of_goods = 0
	for entry in self.get("shipment_delivery_note"):
		value_of_goods += flt(entry.get("grand_total"))
	self.value_of_goods = value_of_goods if value_of_goods else self.value_of_goods

def __init__(self, *args, **kwargs):
	super().__init__(*args, **kwargs)

	# Google Maps returns distances in meters by default
	self.default_distance_uom = (
		frappe.db.get_single_value("Global Defaults", "default_distance_unit") or "Meter"
	)
	self.uom_conversion_factor = frappe.db.get_value(
		"UOM Conversion Factor", {"from_uom": "Meter", "to_uom": self.default_distance_uom}, "value"
	)

def on_discard(self):
	self.update_status()
	self.update_delivery_notes(delete=True)

def after_mapping(self, source_doc):
	for stop in self.delivery_stops[:]:
		if not any(stop.get(df.fieldname) for df in stop.meta.fields):
			self.remove(stop)

def validate(self):
	if self._action == "submit" and not self.driver:
		frappe.throw(_("A driver must be set to submit."))

	if self._action == "submit":
		self.validate_delivery_note_not_draft()
	self.validate_delivery_notes_not_on_other_trips()
	self.validate_stop_addresses()
	self.validate_stop_contacts()

def on_update(self):
	self.update_delivery_notes()
	self.release_removed_delivery_notes()

def on_cancel(self):
	self.update_status()
	self.update_delivery_notes(delete=True)

def validate_stop_addresses(self):
	for stop in self.delivery_stops:
		if stop.address and not stop.customer_address:
			stop.customer_address = get_address_display(frappe.get_doc("Address", stop.address).as_dict())

def validate_stop_contacts(self):
	stops = [stop for stop in self.delivery_stops if stop.contact and stop.customer]
	if not stops:
		return

	dynamic_link = frappe.qb.DocType("Dynamic Link")
	contact_customers = set(
		frappe.qb.from_(dynamic_link)
		.select(dynamic_link.parent, dynamic_link.link_name)
		.where(
			(dynamic_link.parenttype == "Contact")
			& (dynamic_link.link_doctype == "Customer")
			& dynamic_link.parent.isin({stop.contact for stop in stops})
		)
		.run()
	)
	for stop in stops:
		if (stop.contact, stop.customer) not in contact_customers:
			frappe.throw(
				_("Row #{0}: Contact {1} does not belong to Customer {2}").format(
					stop.idx, frappe.bold(stop.contact), frappe.bold(stop.customer)
				)
			)

def validate_delivery_note_not_draft(self):
	delivery_notes = list(set(stop.delivery_note for stop in self.delivery_stops if stop.delivery_note))
	draft_delivery_notes = frappe.get_all(
		"Delivery Note",
		{"docstatus": 0, "name": ["in", delivery_notes]},
		pluck="name",
	)
	if draft_delivery_notes:
		frappe.throw(
			_(
				"Delivery Notes should not be in draft state when submitting a Delivery Trip. The following Delivery Notes are still in draft state: {0}. Please submit them first."
			).format(", ".join(draft_delivery_notes))
		)

def validate_delivery_notes_not_on_other_trips(self):
	delivery_notes = {stop.delivery_note for stop in self.delivery_stops if stop.delivery_note}
	if not delivery_notes:
		return

	delivery_note = frappe.qb.DocType("Delivery Note")
	notes = (
		frappe.qb.from_(delivery_note)
		.select(delivery_note.name, delivery_note.delivery_trip, delivery_note.company)
		.where(delivery_note.name.isin(delivery_notes))
		.for_update()
		.run(as_dict=True)
	)
	if other_company := [d.name for d in notes if self.company and d.company != self.company]:
		frappe.throw(
			_("Delivery Notes {0} do not belong to Company {1}").format(
				", ".join(other_company), frappe.bold(self.company)
			)
		)

	other_trips = {d.delivery_trip for d in notes if d.delivery_trip and d.delivery_trip != self.name}
	open_trips = other_trips and set(
		frappe.get_all(
			"Delivery Trip",
			filters={"name": ("in", list(other_trips)), "docstatus": ("<", 2)},
			pluck="name",
		)
	)
	if linked := [d for d in notes if open_trips and d.delivery_trip in open_trips]:
		frappe.throw(
			_("Delivery Notes are already on another Delivery Trip: {0}").format(
				", ".join(f"{d.name} ({d.delivery_trip})" for d in linked)
			)
		)

def update_status(self):
	status = {0: "Draft", 1: "Scheduled", 2: "Cancelled"}[self.docstatus]

	if self.docstatus == 1:
		visited_stops = [stop.visited for stop in self.delivery_stops]
		if all(visited_stops):
			status = "Completed"
		elif any(visited_stops):
			status = "In Transit"

	self.db_set("status", status)

def release_removed_delivery_notes(self):
	doc_before_save = self.get_doc_before_save()
	if not doc_before_save:
		return

	current = {stop.delivery_note for stop in self.delivery_stops}
	removed = {stop.delivery_note for stop in doc_before_save.delivery_stops if stop.delivery_note}
	if removed - current:
		self.update_delivery_notes(delete=True, delivery_notes=removed - current)

def update_delivery_notes(self, delete=False, delivery_notes=None):
	if delivery_notes is None:
		delivery_notes = {stop.delivery_note for stop in self.delivery_stops if stop.delivery_note}
	if not delivery_notes:
		return

	trip_values = [self.get_delivery_note_values()]
	if doc_before_save := self.get_doc_before_save():
		trip_values.append(doc_before_save.get_delivery_note_values())

	updated = []
	for note in frappe.get_all(
		"Delivery Note",
		filters={"name": ("in", list(delivery_notes))},
		fields=["name", "delivery_trip", *trip_values[0]],
	):
		update = release_delivery_note if delete else link_delivery_note
		if values := update(note, self.name, trip_values):
			frappe.db.set_value("Delivery Note", note.name, values)
			updated.append(get_link_to_form("Delivery Note", note.name))

	if updated:
		frappe.msgprint(_("Delivery Notes {0} updated").format(", ".join(updated)))

def get_delivery_note_values(self):
	return {
		"driver": self.driver,
		"driver_name": self.driver_name,
		"vehicle_no": self.vehicle,
		"lr_no": self.name,
		"lr_date": getdate(self.departure_time) if self.departure_time else None,
	}

def link_delivery_note(note, trip_name, trip_values):
	values = {} if note.delivery_trip == trip_name else {"delivery_trip": trip_name}
	for field, value in trip_values[0].items():
		if note.get(field) != value and (not note.get(field) or is_trip_value(note, field, trip_values)):
			values[field] = value

	return values

def release_delivery_note(note, trip_name, trip_values):
	if note.delivery_trip != trip_name:
		return {}

	values = {"delivery_trip": None}
	for field in trip_values[0]:
		if note.get(field) and is_trip_value(note, field, trip_values):
			values[field] = None

	return values
